629	+    [HttpPost("{id}/buchungen")]
630	+    public async Task<IActionResult> PostBuchung(string id, [FromBody] BuchungAnlegenRequestDto request)
631	+    {
632	+        var ergebnis = await buchungenService.BuchungAnlegenAsync(id, request);
633	+
634	+        return ergebnis.Typ switch
635	+        {
636	+            BuchungErgebnisTyp.Erfolgreich =>
637	+                Created($"/buchungen/{ergebnis.Buchung!.Referenz}", ergebnis.Buchung),
638	+            BuchungErgebnisTyp.VeranstaltungNichtGefunden =>
639	+                NotFound(),
640	+            BuchungErgebnisTyp.PreiskategorieUngueltig =>
641	+                ProblemMitTyp(
642	+                    StatusCodes.Status400BadRequest,
643	+                    "Ungültige Preiskategorie",
644	+                    "preiskategorie_ungueltig",
645	+                    $"Preiskategorie '{ergebnis.UngueltigePreiskategorieId}' gehört nicht zu dieser Veranstaltung."),
646	+            BuchungErgebnisTyp.SitzplatzKonflikt =>

647	+                ProblemMitTyp(
648	+                    StatusCodes.Status409Conflict,
649	+                    "Sitzplatz belegt",
650	+                    "sitzplatz_belegt",
651	+                    "Mindestens einer der gewählten Sitzplätze wurde inzwischen belegt.",
652	+                    ergebnis.BetroffeneSitzplaetze),
653	+            BuchungErgebnisTyp.ReferenzErzeugungFehlgeschlagen =>
654	+                ProblemMitTyp(
655	+                    StatusCodes.Status500InternalServerError,
656	+                    "Buchungsreferenz konnte nicht erzeugt werden",
657	+                    "buchungsreferenz_erzeugung_fehlgeschlagen"),
658	+            _ => throw new InvalidOperationException($"Unbekannter BuchungErgebnisTyp: {ergebnis.Typ}"),
659	+        };
660	+    }
661	+
662	+    private ObjectResult ProblemMitTyp(
663	+        int status,
664	+        string titel,
665	+        string typ,
666	+        string? detail = null,
667	+        IReadOnlyList<string>? betroffeneSitzplaetze = null)
668	+    {
669	+        var problemDetails = new ProblemDetails
670	+        {
671	+            Status = status,
672	+            Title = titel,
673	+            Type = typ,
674	+            Detail = detail,
675	+        };
676	+
677	+        if (betroffeneSitzplaetze is not null)
678	+        {
679	+            problemDetails.Extensions["betroffeneSitzplaetze"] = betroffeneSitzplaetze;
680	+        }
681	+
682	+        return new ObjectResult(problemDetails)
683	+        {
684	+            StatusCode = status,
685	+            ContentTypes = { "application/problem+json" },
686	+        };
687	+    }
688	 }
