1477	+public class BuchungenService(AppDbContext db, IReferenzGenerator referenzGenerator) : IBuchungenService
1478	+{
1479	+    private const int MaxReferenzVersuche = 5;
1480	+
1481	+    public async Task<BuchungErgebnis> BuchungAnlegenAsync(string veranstaltungId, BuchungAnlegenRequestDto request)
1482	+    {
1483	+        var veranstaltung = await db.Veranstaltungen
1484	+            .Include(v => v.Preiskategorien)
1485	+            .FirstOrDefaultAsync(v => v.Id == veranstaltungId);
1486	+
1487	+        if (veranstaltung is null)
1488	+        {
1489	+            return BuchungErgebnis.VeranstaltungFehlt();
1490	+        }
1491	+
1492	+        foreach (var position in request.Positionen)
1493	+        {
1494	+            if (veranstaltung.Preiskategorien.All(p => p.Id != position.PreiskategorieId))
1495	+            {
1496	+                return BuchungErgebnis.PreiskategorieFehlt(position.PreiskategorieId);
1497	+            }
1498	+        }
1499	+
1500	+        var angefragteCodes = request.Positionen.Select(p => p.SitzplatzCode).ToList();
1501	+
1502	+        for (var versuch = 1; versuch <= MaxReferenzVersuche; versuch++)
1503	+        {
1504	+            var buchung = new Buchung
1505	+            {
1506	+                Id = Guid.NewGuid().ToString(),
1507	+                Referenz = referenzGenerator.Naechste(),
1508	+                VeranstaltungId = veranstaltungId,
1509	+                Name = request.Name,
1510	+                Email = request.Email,
1511	+                Status = BuchungStatus.Aktiv,
1512	+                Gesamtpreis = 0m,
1513	+            };
1514	+
1515	+            var positionen = new List<Buchungsposition>();
1516	+            var gesamtpreis = 0m;
1517	+            foreach (var position in request.Positionen)
1518	+            {
1519	+                var kategorie = veranstaltung.Preiskategorien.First(p => p.Id == position.PreiskategorieId);
1520	+                gesamtpreis += kategorie.Preis;
1521	+                positionen.Add(new Buchungsposition
1522	+                {
1523	+                    BuchungId = buchung.Id,
1524	+                    SitzplatzCode = position.SitzplatzCode,
1525	+                    PreiskategorieId = kategorie.Id,
1526	+                    PreisSnapshot = kategorie.Preis,
1527	+                });
1528	+            }
1529	+
1530	+            buchung.Gesamtpreis = gesamtpreis;
1531	+
1532	+            var belegungen = request.Positionen.Select(position => new Sitzplatzbelegung
1533	+            {
1534	+                VeranstaltungId = veranstaltungId,
1535	+                SitzplatzCode = position.SitzplatzCode,
1536	+                BuchungId = buchung.Id,
1537	+            }).ToList();
1538	+
1539	+            await using var transaction = await db.Database.BeginTransactionAsync();
1540	+            db.Buchungen.Add(buchung);
1541	+            db.Buchungspositionen.AddRange(positionen);
1542	+            db.Sitzplatzbelegungen.AddRange(belegungen);
1543	+
1544	+            try
1545	+            {
1546	+                await db.SaveChangesAsync();
1547	+                await transaction.CommitAsync();
1548	+
1549	+                return BuchungErgebnis.Erfolg(new BuchungDto(
1550	+                    buchung.Referenz,
1551	+                    buchung.VeranstaltungId,
1552	+                    buchung.Name,
1553	+                    buchung.Email,
1554	+                    buchung.Status.ToString(),
1555	+                    buchung.Gesamtpreis,
1556	+                    positionen.Select(p => new BuchungspositionDto(
1557	+                        p.SitzplatzCode,
1558	+                        p.PreiskategorieId,
1559	+                        veranstaltung.Preiskategorien.First(k => k.Id == p.PreiskategorieId).Name,
1560	+                        p.PreisSnapshot)).ToList()));
1561	+            }
1562	+            catch (DbUpdateException)
1563	+            {
1564	+                await transaction.RollbackAsync();
1565	+                db.ChangeTracker.Clear();
1566	+
1567	+                var tatsaechlichBelegt = await db.Sitzplatzbelegungen
1568	+                    .Where(s => s.VeranstaltungId == veranstaltungId && angefragteCodes.Contains(s.SitzplatzCode))
1569	+                    .Select(s => s.SitzplatzCode)
1570	+                    .ToListAsync();
1571	+
1572	+                if (tatsaechlichBelegt.Count > 0)
1573	+                {
1574	+                    return BuchungErgebnis.Konflikt(tatsaechlichBelegt);
1575	+                }
1576	+
1577	+                // Keiner der angefragten Plaetze ist tatsaechlich belegt: der Fehlschlag kam nicht von
1578	+                // Sitzplatzbelegung, sondern von der UNIQUE-Constraint auf Buchung.Referenz. Naechster
1579	+                // Versuch mit neuer Referenz (bis MaxReferenzVersuche erreicht ist).
1580	+            }
1581	+        }
1582	+
1583	+        return BuchungErgebnis.ReferenzFehlgeschlagen();
1584	+    }
1585	+}
