6	namespace seed_a_backend.Api.Services;
7	
8	public class BuchungenService(AppDbContext db, IReferenzGenerator referenzGenerator) : IBuchungenService
9	{
10	    private const int MaxReferenzVersuche = 5;
11	
12	    public async Task<BuchungErgebnis> BuchungAnlegenAsync(string veranstaltungId, BuchungAnlegenRequestDto request)
13	    {
14	        var veranstaltung = await db.Veranstaltungen
15	            .Include(v => v.Preiskategorien)
16	            .FirstOrDefaultAsync(v => v.Id == veranstaltungId);
17	
18	        if (veranstaltung is null)
19	        {
20	            return BuchungErgebnis.VeranstaltungFehlt();
21	        }
22	
23	        foreach (var position in request.Positionen)
24	        {
25	            if (veranstaltung.Preiskategorien.All(p => p.Id != position.PreiskategorieId))
26	            {
27	                return BuchungErgebnis.PreiskategorieFehlt(position.PreiskategorieId);
28	            }
29	        }
30	
31	        var angefragteCodes = request.Positionen.Select(p => p.SitzplatzCode).ToList();
32	
33	        for (var versuch = 1; versuch <= MaxReferenzVersuche; versuch++)
34	        {
35	            var buchung = new Buchung
36	            {
37	                Id = Guid.NewGuid().ToString(),
38	                Referenz = referenzGenerator.Naechste(),
39	                VeranstaltungId = veranstaltungId,
40	                Name = request.Name,
41	                Email = request.Email,
42	                Status = BuchungStatus.Aktiv,
43	                Gesamtpreis = 0m,
44	            };
45	
46	            var positionen = new List<Buchungsposition>();
47	            var gesamtpreis = 0m;
48	            foreach (var position in request.Positionen)
49	            {
50	                var kategorie = veranstaltung.Preiskategorien.First(p => p.Id == position.PreiskategorieId);
51	                gesamtpreis += kategorie.Preis;
52	                positionen.Add(new Buchungsposition
53	                {
54	                    BuchungId = buchung.Id,
55	                    SitzplatzCode = position.SitzplatzCode,
56	                    PreiskategorieId = kategorie.Id,
57	                    PreisSnapshot = kategorie.Preis,
58	                });
59	            }
60	
61	            buchung.Gesamtpreis = gesamtpreis;
62	
63	            var belegungen = request.Positionen.Select(position => new Sitzplatzbelegung
64	            {
65	                VeranstaltungId = veranstaltungId,
66	                SitzplatzCode = position.SitzplatzCode,
67	                BuchungId = buchung.Id,
68	            }).ToList();
69	
70	            await using var transaction = await db.Database.BeginTransactionAsync();
71	            db.Buchungen.Add(buchung);
72	            db.Buchungspositionen.AddRange(positionen);
73	            db.Sitzplatzbelegungen.AddRange(belegungen);
74	
75	            try
76	            {
77	                await db.SaveChangesAsync();
78	                await transaction.CommitAsync();
79	
80	                return BuchungErgebnis.Erfolg(new BuchungDto(
81	                    buchung.Referenz,
