1	using Microsoft.EntityFrameworkCore;
2	using seed_a_backend.Api.Data;
3	using seed_a_backend.Api.DTOs;
4	using seed_a_backend.Api.Models;
5	using seed_a_backend.Api.Services;
6	using seed_a_backend.Tests.TestSupport;
7	
8	namespace seed_a_backend.Tests;
9	
10	public class BuchungenServiceTests : IAsyncLifetime
11	{
12	    private AppDbContext _db = null!;
13	
14	    public async ValueTask InitializeAsync()
15	    {
16	        _db = await SqlServerTestDatabase.CreateFreshContextAsync(nameof(BuchungenServiceTests));
17	    }
18	
19	    public async ValueTask DisposeAsync()
20	    {
21	        await _db.Database.EnsureDeletedAsync();
22	        await _db.DisposeAsync();
23	    }
24	
25	    private sealed class ImmerGleicheReferenz(string referenz) : IReferenzGenerator
26	    {
27	        public string Naechste() => referenz;
28	    }
29	
30	    private async Task SeedVeranstaltungMitZweiPreiskategorienAsync()
31	    {
32	        _db.Spielstaetten.Add(new Spielstaette { Id = "V1", Name = "Testspielstätte" });
33	        _db.Raeume.Add(new Raum { Id = "R1", Name = "Testraum", SpielstaetteId = "V1", Reihen = ["A", "B"], Spalten = 4, GangSpalten = [] });
34	        _db.Veranstaltungen.Add(new Veranstaltung
35	        {
36	            Id = "E1",
37	            Titel = "Test",
38	            Beschreibung = "-",
39	            RaumId = "R1",
40	            DauerMinuten = 60,
41	            Altersfreigabe = 0,
42	            Zeitpunkt = new DateTimeOffset(2026, 9, 1, 20, 0, 0, TimeSpan.Zero)
43	        });
44	        _db.Preiskategorien.AddRange(
45	            new Preiskategorie { Id = "E1-A", Name = "Kategorie A", Preis = 32.00m, VeranstaltungId = "E1" },
46	            new Preiskategorie { Id = "E1-B", Name = "Kategorie B", Preis = 22.00m, VeranstaltungId = "E1" });
47	        await _db.SaveChangesAsync();
48	    }
49	
50	    [Fact]
51	    public async Task BuchungAnlegenAsync_GueltigeAuswahl_LegtBuchungPositionenUndBelegungenAn()
52	    {
53	        await SeedVeranstaltungMitZweiPreiskategorienAsync();
54	        var service = new BuchungenService(_db, new ReferenzGenerator());
55	        var request = new BuchungAnlegenRequestDto(
56	            "Max Mustermann",
57	            "max@example.com",
58	            [
59	                new BuchungspositionRequestDto("A1", "E1-A"),
60	                new BuchungspositionRequestDto("A2", "E1-B"),
61	            ]);
62	
63	        var ergebnis = await service.BuchungAnlegenAsync("E1", request);
64	
65	        Assert.Equal(BuchungErgebnisTyp.Erfolgreich, ergebnis.Typ);
66	        Assert.NotNull(ergebnis.Buchung);
67	        Assert.Equal(8, ergebnis.Buchung!.Referenz.Length);
68	        Assert.All(ergebnis.Buchung.Referenz, c => Assert.Contains(c, "0123456789ABCDEFGHJKMNPQRSTVWXYZ"));
69	        Assert.Equal(54.00m, ergebnis.Buchung.Gesamtpreis);
70	
71	        Assert.Equal(1, await _db.Buchungen.CountAsync());
72	        Assert.Equal(2, await _db.Buchungspositionen.CountAsync());
73	        Assert.Equal(2, await _db.Sitzplatzbelegungen.CountAsync());
74	    }
75	
76	    [Fact]
77	    public async Task BuchungAnlegenAsync_EinPlatzBereitsBelegt_LiefertKonfliktUndLegtKeineTeilbuchungAn()
78	    {
79	        await SeedVeranstaltungMitZweiPreiskategorienAsync();
80	        _db.Sitzplatzbelegungen.Add(new Sitzplatzbelegung { VeranstaltungId = "E1", SitzplatzCode = "A1", BuchungId = null });
81	        await _db.SaveChangesAsync();
82	        _db.ChangeTracker.Clear(); // simuliert einen frischen Request-Context, der die zuvor gesetzte Belegung nicht mehr lokal trackt
83	        var service = new BuchungenService(_db, new ReferenzGenerator());
84	        var request = new BuchungAnlegenRequestDto(
85	            "Max Mustermann",
86	            "max@example.com",
87	            [
88	                new BuchungspositionRequestDto("A1", "E1-A"),
89	                new BuchungspositionRequestDto("A2", "E1-B"),
90	            ]);
91	
92	        var ergebnis = await service.BuchungAnlegenAsync("E1", request);
93	
94	        Assert.Equal(BuchungErgebnisTyp.SitzplatzKonflikt, ergebnis.Typ);
95	        Assert.Equal(["A1"], ergebnis.BetroffeneSitzplaetze);
96	
97	        Assert.Equal(0, await _db.Buchungen.CountAsync());
98	        Assert.False(await _db.Sitzplatzbelegungen.AnyAsync(s => s.SitzplatzCode == "A2"));
99	    }
100	
101	    [Fact]
102	    public async Task BuchungAnlegenAsync_PreiskategorieGehoertZuAndererVeranstaltung_LiefertPreiskategorieUngueltig()
103	    {
104	        await SeedVeranstaltungMitZweiPreiskategorienAsync();
105	        _db.Veranstaltungen.Add(new Veranstaltung
106	        {
107	            Id = "E2",
108	            Titel = "Andere Veranstaltung",
109	            Beschreibung = "-",
110	            RaumId = "R1",
111	            DauerMinuten = 60,
112	            Altersfreigabe = 0,
113	            Zeitpunkt = new DateTimeOffset(2026, 9, 2, 20, 0, 0, TimeSpan.Zero)
114	        });
115	        _db.Preiskategorien.Add(new Preiskategorie { Id = "E2-A", Name = "Kategorie A", Preis = 15.00m, VeranstaltungId = "E2" });
116	        await _db.SaveChangesAsync();
117	        var service = new BuchungenService(_db, new ReferenzGenerator());
118	        var request = new BuchungAnlegenRequestDto(
119	            "Max Mustermann",
120	            "max@example.com",
121	            [new BuchungspositionRequestDto("A1", "E2-A")]);
122	
123	        var ergebnis = await service.BuchungAnlegenAsync("E1", request);
124	
125	        Assert.Equal(BuchungErgebnisTyp.PreiskategorieUngueltig, ergebnis.Typ);
126	        Assert.Equal("E2-A", ergebnis.UngueltigePreiskategorieId);
127	        Assert.Equal(0, await _db.Buchungen.CountAsync());
128	    }
129	
130	    [Fact]
131	    public async Task BuchungAnlegenAsync_FuenfReferenzKollisionenInFolge_LiefertReferenzErzeugungFehlgeschlagen()
132	    {
133	        await SeedVeranstaltungMitZweiPreiskategorienAsync();
134	        _db.Buchungen.Add(new Buchung
135	        {
136	            Id = Guid.NewGuid().ToString(),
137	            Referenz = "AAAAAAAA",
138	            VeranstaltungId = "E1",
139	            Name = "Bestehend",
140	            Email = "bestehend@example.com",
141	            Status = BuchungStatus.Aktiv,
142	            Gesamtpreis = 32.00m,
